/**
 * Writes tests/SCENARIOS.md: every spec scenario and the tests whose titles name it.
 * Exits with code 1 when a scenario has no test. Run with: pnpm scenarios
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { join, relative } from 'node:path';

const ROOT = join(import.meta.dirname, '..', '..', '..');
const CHANGES = ['local-pr-review-app', 'dependency-map'];
const TESTS = join(ROOT, 'tests');
const OUTPUT = join(TESTS, 'SCENARIOS.md');
const MAX_TESTS_LISTED = 4;

interface Scenario {
  capability: string;
  requirement: string;
  name: string;
}

interface TestTitle {
  file: string;
  title: string;
}

const normalise = (text: string): string =>
  text
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();

const readScenarios = async (change: string): Promise<Scenario[]> => {
  const specs = join(ROOT, 'openspec', 'changes', change, 'specs');
  const scenarios: Scenario[] = [];
  for (const capability of (await readdir(specs)).sort()) {
    let requirement = '';
    for (const line of (await readFile(join(specs, capability, 'spec.md'), 'utf8')).split('\n')) {
      requirement = /^### Requirement: (.+)/.exec(line)?.[1]?.trim() ?? requirement;
      const name = /^#### Scenario: (.+)/.exec(line)?.[1]?.trim();
      if (name !== undefined) {
        scenarios.push({ capability, requirement, name });
      }
    }
  }
  return scenarios;
};

const TITLE = /\b(?:it|test)(?:\.each\([\s\S]*?\))?\(\s*(['"`])((?:\\.|(?!\1).)*)\1/g;

const readTestTitles = async (): Promise<TestTitle[]> => {
  const titles: TestTitle[] = [];
  for (const entry of await readdir(TESTS, { recursive: true })) {
    if (!/\.(test|spec)\.ts$/.test(entry)) {
      continue;
    }
    const text = await readFile(join(TESTS, entry), 'utf8');
    for (const match of text.matchAll(TITLE)) {
      titles.push({ file: relative(ROOT, join(TESTS, entry)), title: match[2] ?? '' });
    }
  }
  return titles;
};

/** Tests whose title starts with the scenario name, or failing that, mentions it. */
const testsFor = (scenario: Scenario, titles: TestTitle[]): TestTitle[] => {
  const name = normalise(scenario.name);
  const exact = titles.filter((test) => normalise(test.title).startsWith(name));
  return exact.length > 0 ? exact : titles.filter((test) => normalise(test.title).includes(name));
};

const main = async (): Promise<void> => {
  const [perChange, titles] = await Promise.all([
    Promise.all(CHANGES.map(readScenarios)),
    readTestTitles(),
  ]);
  const scenarios = perChange.flat();
  const lines = [
    '# Scenario coverage',
    '',
    `Every scenario in the specs of ${CHANGES.map((change) => `\`openspec/changes/${change}\``).join(' and ')}, and the tests that exercise it.`,
    'Generated by `pnpm scenarios`, which fails when a scenario has no test.',
  ];
  let capability = '';
  const unmapped: Scenario[] = [];
  for (const scenario of scenarios) {
    if (scenario.capability !== capability) {
      capability = scenario.capability;
      lines.push(
        '',
        `## ${capability}`,
        '',
        '| Requirement | Scenario | Tests |',
        '| --- | --- | --- |',
      );
    }
    const tests = testsFor(scenario, titles);
    if (tests.length === 0) {
      unmapped.push(scenario);
    }
    const cell =
      tests
        .slice(0, MAX_TESTS_LISTED)
        .map((test) => `\`${test.file}\`: ${test.title.replaceAll('|', '/')}`)
        .join('<br>') || '**none**';
    lines.push(`| ${scenario.requirement} | ${scenario.name} | ${cell} |`);
  }
  await writeFile(OUTPUT, `${lines.join('\n')}\n`);
  process.stdout.write(
    `${scenarios.length - unmapped.length} of ${scenarios.length} scenarios have tests\n`,
  );
  for (const scenario of unmapped) {
    process.stdout.write(
      `  missing: ${scenario.capability} / ${scenario.requirement} / ${scenario.name}\n`,
    );
  }
  process.exitCode = unmapped.length === 0 ? 0 : 1;
};

await main();
